"""Independent saved-native prop transforms vs authoring state at sampled frames."""
import bpy,json,gzip,sys,numpy as np
from pathlib import Path
from mathutils import Vector,Matrix
R=Path(__file__).resolve().parents[1];versions=json.loads((R/'reports/SHOT_REVISIONS.json').read_text());B=Matrix(((0,0,1),(1,0,0),(0,1,0)));results={}
for shot in ['KEY_LOCK','DOOR_ENTRY','DRIVING_COCKPIT','WINDOW_CURTAIN']:
 tag=versions[shot];d=json.load(gzip.open(R/'scenes'/f'{shot}_{tag}.json.gz','rt'));bpy.ops.wm.open_mainfile(filepath=str(R/'blender'/f'{shot}_{tag}.blend'));sc=bpy.context.scene;err=0.;count=0;tests=[]
 for i in sorted({0,len(d['frames'])//4,len(d['frames'])//2,len(d['frames'])*3//4,len(d['frames'])-1}):
  sc.frame_set(i);bpy.context.view_layer.update();s=d['state'][i];pairs=[]
  if shot in ['KEY_LOCK','DOOR_ENTRY']:pairs=[('PROP_DOOR_HINGE',[.45,0,0],'door_R'),('PROP_KEY_BOW',s['keybow'],'key_R'),('PROP_HANDLE_SPINDLE',s['spindle'],'handle_R')]
  elif shot=='DRIVING_COCKPIT':pairs=[('STEERING_COLUMN_AXIS',s['wheel_center'],'wheel_R')]
  for name,pos,rot in pairs:
   o=bpy.data.objects[name];err=max(err,(o.matrix_world.translation-B@Vector(pos)).length);actual=o.matrix_world.to_3x3();want=B@Matrix(s[rot])@B.transposed();err=max(err,max(abs(actual[j][k]-want[j][k]) for j in range(3) for k in range(3)));count+=1;tests.append(name)
  if shot=='WINDOW_CURTAIN':
   o=bpy.data.objects['RIGGED_FABRIC_MATERIAL_WIDTH_1_60m'];ev=o.evaluated_get(bpy.context.evaluated_depsgraph_get());m=ev.to_mesh();want=np.array(s['fabric']).reshape(-1,3)
   for v,q in zip(m.vertices,want):err=max(err,(ev.matrix_world@v.co-B@Vector(q)).length);count+=1
   ev.to_mesh_clear();tests.append('native fabric shape-key evaluated grid')
 results[shot]={'native_tag':tag,'samples':count,'tested_objects':sorted(set(tests)),'max_translation_or_matrix_component_error':err,'tolerance':.00001,'technical_status':'TECHNICAL PASS' if err<.00001 else 'TECHNICAL FAIL','units':'Translation/fabric errors metres; rotation matrix errors dimensionless, combined maximum reported conservatively','limits':'Sampled editable mirror parity only. Cinematic props are generated by scripts; changing native props alone does not update that renderer.'};print(shot,err,flush=True)
(R/'reports/NATIVE_PROP_PARITY.json').write_text(json.dumps(results,indent=2))
